// A paleta do Lens, em duas camadas:
//
// - COR: as cores de texto e de moldura, como chaves do tema do Claude Code.
//   Cada chave tem um valor para o tema claro, o escuro e os de daltonismo,
//   então o texto colorido se lê em qualquer um deles.
// - TONS: os selos (texto sobre fundo colorido), em cores cruas, cada fundo
//   com a tinta que contrasta com ele: como o Lens pinta os dois, valem
//   iguais em qualquer tema. Também são as cores dos gráficos em SVG, que não
//   conhecem o tema.

export type Tom = {
  fundo: string
  tinta: string
}

const ESCURA = '#0d1117'
const CLARA = '#ffffff'

export const TONS = {
  // O azul-celeste do Grêmio.
  marca: { fundo: '#0d80bf', tinta: CLARA },
  rotulo: { fundo: '#30363d', tinta: '#e6edf3' },
  verde: { fundo: '#3fb950', tinta: ESCURA },
  ambar: { fundo: '#d29922', tinta: ESCURA },
  vermelho: { fundo: '#f85149', tinta: CLARA },
  azul: { fundo: '#58a6ff', tinta: ESCURA },
  roxo: { fundo: '#a371f7', tinta: CLARA },
  ciano: { fundo: '#39c5cf', tinta: ESCURA },
  laranja: { fundo: '#f0883e', tinta: ESCURA },
  cinza: { fundo: '#6e7681', tinta: CLARA },
  // A faixa do item escolhido numa lista, como a seleção do VS Code.
  selecao: { fundo: '#264f78', tinta: CLARA },
} as const satisfies Record<string, Tom>

export type NomeDoTom = keyof typeof TONS

// As cores de texto, pelo tema.
export const COR = {
  marca: 'claude',
  verde: 'success',
  ambar: 'warning',
  vermelho: 'error',
  azul: 'suggestion',
  roxo: 'merged',
  ciano: 'planMode',
  laranja: 'claude',
  cinza: 'inactive',
} as const

export type NomeDaCor = keyof typeof COR

// O selo que corresponde a uma cor de texto (a chave do tema): o mesmo matiz,
// com a tinta que contrasta com o fundo. A cor do Claude vira o laranja.
const TOM_DA_COR: Readonly<Record<string, NomeDoTom>> = {
  claude: 'laranja',
  success: 'verde',
  warning: 'ambar',
  error: 'vermelho',
  suggestion: 'azul',
  merged: 'roxo',
  planMode: 'ciano',
  inactive: 'cinza',
}

export const tomDaCor = (cor: string): Tom => TONS[TOM_DA_COR[cor] ?? 'rotulo']

// Verde até a metade, âmbar até 80%, vermelho daí para cima.
export const tomDoNivel = (percentual: number): 'verde' | 'ambar' | 'vermelho' =>
  percentual >= 80 ? 'vermelho' : percentual >= 50 ? 'ambar' : 'verde'

// A mesma escala, como cor de texto.
export const corDoNivel = (percentual: number): string => COR[tomDoNivel(percentual)]

