// O desenho da aba Inventário: uma seção por tipo de peça (plugins, skills,
// comandos, agentes, hooks, MCP, o resto e o que dá para instalar), cada
// peça com a origem, a descrição e se está ativa nesta sessão.

import type { RenderElement } from 'claude-code'

import type { LensItem, LensSecaoDoInventario, LensTipoDeItem } from '../types'
import { COR } from './cores'
import { duracao, plural } from './formato'
import { cartao, comMoldura, comTecla, secao, selo } from './pecas'
import type { Acoes, Dados, Elementos, Quadro } from './telas'

export const SECOES: readonly {
  id: LensSecaoDoInventario
  nome: string
  tipos: readonly LensTipoDeItem[]
  ajuda: string
}[] = [
  { id: 'plugin', nome: 'Plugins', tipos: ['plugin'], ajuda: 'Instalados; ativo é o habilitado nas configurações.' },
  { id: 'skill', nome: 'Skills', tipos: ['skill'], ajuda: 'Ativa é a que o modelo vê listada nesta sessão.' },
  { id: 'comando', nome: 'Comandos', tipos: ['comando'], ajuda: 'Os comandos de barra que você pode rodar agora.' },
  { id: 'agente', nome: 'Agentes', tipos: ['agente'], ajuda: 'Os tipos de subagente além dos embutidos.' },
  { id: 'hook', nome: 'Hooks', tipos: ['hook'], ajuda: 'Das configurações e dos plugins; o comando que roda em cada evento.' },
  { id: 'mcp', nome: 'MCP', tipos: ['mcp'], ajuda: 'Servidores conectados, pelas ferramentas que a sessão tem deles.' },
  {
    id: 'outros',
    nome: 'Outros',
    tipos: ['estilo', 'memoria', 'ferramenta'],
    ajuda: 'Estilos de saída, arquivos de memória (CLAUDE.md) e ferramentas embutidas.',
  },
  {
    id: 'disponivel',
    nome: 'Para instalar',
    tipos: ['disponivel'],
    ajuda: 'Nos marketplaces que você adicionou, ainda não instalados: /plugin install nome@marketplace.',
  },
]

const COR_DO_INVENTARIO = COR.ambar
// Quantos itens aparecem de cada vez: 200 cartões numa tela só (um marketplace
// grande no "Para instalar") travavam o app. O "Mostrar mais" soma outros 30.
export const ITENS_POR_VEZ = 30

const NOMES_DOS_TIPOS: Readonly<Record<LensTipoDeItem, string>> = {
  plugin: 'plugin',
  disponivel: 'disponível',
  skill: 'skill',
  comando: 'comando',
  agente: 'agente',
  hook: 'hook',
  mcp: 'MCP',
  estilo: 'estilo de saída',
  memoria: 'memória',
  ferramenta: 'ferramenta',
}

const nomeDoItem = (item: LensItem): string => (item.tipo === 'comando' ? `/${item.nome}` : item.nome)

const linhaDoItem = (el: Elementos, item: LensItem, quadro: Quadro, i: number): RenderElement => {
  const { Box, Text } = el
  const chave = `item-${i}-${item.tipo}-${item.origem}-${item.nome}-${item.extra ?? ''}`
  const isDisponivel = item.tipo === 'disponivel'
  const marca = item.isAtivo ? '●' : '○'
  const cor = item.isAtivo ? COR.verde : COR.cinza

  if (quadro.isCompacto) {
    return (
      <Text wrap="truncate-end">
        <Text color={cor}>{`${marca} `}</Text>
        <Text bold={item.isAtivo} dimColor={!item.isAtivo}>{nomeDoItem(item)}</Text>
        {item.descricao !== undefined && <Text dimColor>{` · ${item.descricao}`}</Text>}
      </Text>
    )
  }

  // Cada item num cartão, como os dos agentes: a moldura na cor do estado.
  return cartao(el, chave, isDisponivel ? COR.azul : cor, false, [
    <Box key={`${chave}-cabeca`} flexDirection="row" columnGap={1}>
      <Box flexGrow={1} flexShrink={1} minWidth={0}>
        <Text wrap="truncate-end">
          <Text color={isDisponivel ? COR.azul : cor}>{isDisponivel ? '+ ' : `${marca} `}</Text>
          <Text bold={item.isAtivo || isDisponivel} dimColor={!item.isAtivo && !isDisponivel}>
            {nomeDoItem(item)}
          </Text>
          {item.extra !== undefined && <Text color={COR_DO_INVENTARIO}>{`  ${item.extra}`}</Text>}
        </Text>
      </Box>
      {!isDisponivel && (
        // Numa Box que não encolhe: o selo nunca quebra em duas linhas.
        <Box flexShrink={0}>
          {item.isAtivo ? selo(el, 'ativo', 'verde', false) : selo(el, 'inativo', 'cinza', false)}
        </Box>
      )}
    </Box>,
    item.descricao !== undefined && (
      <Text key={`${chave}-descricao`} dimColor wrap="wrap">{item.descricao}</Text>
    ),
    item.detalhe !== undefined && (
      <Text key={`${chave}-detalhe`} color={COR.ciano} wrap="wrap">{item.detalhe}</Text>
    ),
  ])
}

// Os itens de uma seção, agrupados pela origem: os grupos com algo ativo
// primeiro, e dentro de cada um os ativos antes.
const grupos = (itens: readonly LensItem[]): [string, LensItem[]][] => {
  const porOrigem = new Map<string, LensItem[]>()

  for (const item of itens) {
    porOrigem.set(item.origem, [...(porOrigem.get(item.origem) ?? []), item])
  }

  return [...porOrigem.entries()]
    .map(([origem, lista]): [string, LensItem[]] => [
      origem,
      [...lista].sort((a, b) => Number(b.isAtivo) - Number(a.isAtivo) || a.nome.localeCompare(b.nome)),
    ])
    .sort(
      (a, b) =>
        Number(b[1].some(item => item.isAtivo)) - Number(a[1].some(item => item.isAtivo)) ||
        a[0].localeCompare(b[0]),
    )
}

export const abaInventario = (
  el: Elementos,
  dados: Dados,
  quadro: Quadro,
  acoes: Acoes,
): RenderElement => {
  const { Box, Button, Input, Text } = el
  const atual = dados.ui.secaoDoInventario ?? 'plugin'
  const filtro = (dados.ui.filtroDoInventario ?? '').trim().toLowerCase()
  const todos = dados.inventario.itens
  const daSecao = (id: LensSecaoDoInventario) => {
    const tipos = SECOES.find(uma => uma.id === id)?.tipos ?? []

    return todos.filter(item => tipos.includes(item.tipo))
  }
  const escolhida = SECOES.find(uma => uma.id === atual) ?? SECOES[0]
  const itens = daSecao(atual).filter(
    item =>
      filtro === '' ||
      [item.nome, item.origem, item.descricao ?? '', item.extra ?? '', item.detalhe ?? '']
        .join(' ')
        .toLowerCase()
        .includes(filtro),
  )
  const lido = dados.inventario.lidoEm
  const visiveis = itens.slice(0, quadro.isCompacto ? 4 : (dados.ui.itensDoInventario ?? ITENS_POR_VEZ))

  const seletor = SECOES.map(uma => {
    const daUma = daSecao(uma.id)
    const ativos = daUma.filter(item => item.isAtivo).length
    const rotulo =
      uma.id === 'disponivel' ? `${uma.nome} ${daUma.length}` : `${uma.nome} ${ativos}/${daUma.length}`

    return uma.id === atual ? (
      selo(el, rotulo, 'ambar')
    ) : (
      <Box key={`guia-inv-${uma.id}`}>
        <Button
          key={`inv-${uma.id}`}
          label={rotulo}
          {...comMoldura(quadro)}
          hover={{ color: COR_DO_INVENTARIO, bold: true }}
          onPress={() => acoes.secao(uma.id)}
        />
      </Box>
    )
  })

  return (
    <Box key="inventario" flexDirection="column" rowGap={quadro.isCompacto ? 0 : 1}>
      <Box flexDirection="column">
        {secao(
          el,
          'Inventário',
          COR_DO_INVENTARIO,
          lido === undefined
            ? '· lendo…'
            : quadro.agora - lido < 5000
              ? '· atualizado agora · sem gastar tokens'
              : `· atualizado há ${duracao(quadro.agora - lido)} · sem gastar tokens`,
          quadro.isTerminal || quadro.isCompacto ? undefined : quadro.largura,
          quadro.tomDaAba,
        )}
        {/* Uma folga entre a faixa do título e as seções (no app, colados, os
            botões pareciam pendurados na faixa). */}
        <Box flexDirection="row" flexWrap="wrap" columnGap={2} rowGap={quadro.isTerminal ? 0 : 1} marginTop={quadro.isTerminal ? 0 : 1}>
          {seletor}
        </Box>
      </Box>
      {!quadro.isCompacto && (
        <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
          <Button key="inventario-atualizar" label={comTecla(quadro, '↻ Atualizar', 'u')} hotkey="u" onPress={acoes.atualizarInventario} />
          <Button key="inventario-anterior" label={comTecla(quadro, '‹ Seção', 'j')} hotkey="j" onPress={() => acoes.secaoVizinha(-1)} />
          <Button key="inventario-proxima" label={comTecla(quadro, 'Seção ›', 'k')} hotkey="k" onPress={() => acoes.secaoVizinha(1)} />
        </Box>
      )}
      {!quadro.isCompacto && Input !== null && (
        <Input
          key="filtro-inventario"
          label="Filtro"
          placeholder="nome, origem ou descrição"
          value={dados.ui.filtroDoInventario ?? ''}
          submitLabel="filtrar"
          onInput={texto => acoes.filtroDoInventario(texto)}
          onSubmit={texto => acoes.filtroDoInventario(texto)}
        />
      )}
      {!quadro.isCompacto && escolhida !== undefined && (
        <Box flexDirection="column">
          <Text dimColor wrap="wrap">{escolhida.ajuda}</Text>
          {/* O resumo da seção: quantos, quantos ativos e de quantas origens. */}
          {itens.length > 0 && (
            <Text wrap="wrap">
              <Text bold>{plural(itens.length, NOMES_DOS_TIPOS[escolhida.tipos[0] ?? 'plugin'], `${NOMES_DOS_TIPOS[escolhida.tipos[0] ?? 'plugin']}s`)}</Text>
              {atual !== 'disponivel' && (
                <Text color={COR.verde}>{` · ${plural(itens.filter(item => item.isAtivo).length, 'ativo', 'ativos')}`}</Text>
              )}
              {atual !== 'disponivel' && itens.some(item => !item.isAtivo) && (
                <Text dimColor>{` · ${plural(itens.filter(item => !item.isAtivo).length, 'inativo', 'inativos')}`}</Text>
              )}
              <Text dimColor>{` · ${plural(new Set(itens.map(item => item.origem)).size, 'origem', 'origens')}`}</Text>
            </Text>
          )}
        </Box>
      )}
      {itens.length === 0 && (
        <Text dimColor>
          {lido === undefined
            ? 'Lendo o que está instalado…'
            : filtro === ''
              ? `Nenhum ${NOMES_DOS_TIPOS[escolhida?.tipos[0] ?? 'plugin']} encontrado.`
              : 'Nada passa no filtro.'}
        </Text>
      )}
      {quadro.isCompacto
        ? visiveis.map((item, i) => linhaDoItem(el, item, quadro, i))
        : grupos(visiveis).map(([origem, lista]) => {
            // O nome do grupo abre e fecha os itens dele; aberto, eles vêm
            // em cartões, um embaixo do outro.
            const chave = `${atual}:${origem}`
            const isFechado = (dados.ui.gruposFechados ?? []).includes(chave)
            const ativos = lista.filter(item => item.isAtivo).length

            return (
              // Os cartões com uma linha de folga entre eles (colados, um
              // parecia a continuação do outro).
              <Box key={`grupo-${origem}`} flexDirection="column" rowGap={quadro.isTerminal ? 0 : 1}>
                <Box flexDirection="row" columnGap={1}>
                  <Box flexShrink={0}>
                    <Button
                      key={`grupo-inv-${origem}`}
                      label={`${isFechado ? '▸' : '▾'} ${origem}`}
                      {...comMoldura(quadro)}
                      hover={{ color: COR_DO_INVENTARIO, bold: true }}
                      onPress={() => acoes.grupoDoInventario(chave)}
                    />
                  </Box>
                  <Box flexGrow={1} flexShrink={1} minWidth={0}>
                    <Text dimColor wrap="truncate-end">
                      {`${plural(lista.length, 'item', 'itens')}${atual === 'disponivel' ? '' : ` · ${plural(ativos, 'ativo', 'ativos')}`}${isFechado ? ' · fechado' : ''}`}
                    </Text>
                  </Box>
                </Box>
                {!isFechado && lista.map((item, i) => linhaDoItem(el, item, quadro, i))}
              </Box>
            )
          })}
      {itens.length > visiveis.length &&
        (quadro.isCompacto ? (
          <Text dimColor>{`… mais ${plural(itens.length - visiveis.length, 'item', 'itens')}`}</Text>
        ) : (
          <Box key="inventario-mais" flexDirection="row" columnGap={1}>
            <Button
              key="inventario-mais"
              label={`Mostrar mais ${Math.min(ITENS_POR_VEZ, itens.length - visiveis.length)}`}
              {...comMoldura(quadro)}
              onPress={acoes.maisDoInventario}
            />
            <Text dimColor>{`${visiveis.length} de ${itens.length} · o filtro procura em todos`}</Text>
          </Box>
        ))}
    </Box>
  )
}

files.hooks/caminhos-do-bash.ts:
// Os arquivos que um comando Bash lê e escreve, adivinhados pelo texto do
// comando: os subagentes tocam arquivo por cat, sed, grep, redirecionamento,
// e a aba Árvore só via os Read/Edit/Write. Função pura, sem olhar o disco:
// um palpite bom, não uma certeza. Nunca lança: devolve o que achou.

export type ArquivoDoComando = { caminho: string; acao: 'lendo' | 'editando' }

type Acao = ArquivoDoComando['acao']
type Anotar = (texto: string, acao: Acao) => void
type Palavra = { texto: string; redireciona?: Acao | 'nada' }

const MAX_ARQUIVOS = 30

// Palavras antes do comando que só mudam como ele roda.
const PREFIXOS = new Set(['sudo', 'time', 'command', 'env', 'nohup', 'exec', 'builtin'])

// Comandos cujos argumentos são arquivos lidos.
const LEITORES = new Set([
  'cat', 'head', 'tail', 'less', 'more', 'wc', 'nl', 'sort', 'uniq', 'diff', 'cmp', 'file', 'stat',
  'md5', 'md5sum', 'shasum', 'sha1sum', 'sha256sum', 'bat', 'tac', 'strings', 'source', '.',
])
// Comandos cujos argumentos são arquivos escritos (o mv conta os dois lados).
const EDITORES = new Set(['tee', 'rm', 'mv'])
const PADROES = new Set(['grep', 'egrep', 'fgrep', 'rg', 'ugrep', 'ag'])
const AWKS = new Set(['awk', 'gawk', 'mawk'])
const INTERPRETES = new Set(['python', 'python3', 'python2', 'node', 'bash', 'sh', 'zsh', 'ruby'])

// Opções que engolem o argumento seguinte, por comando: cada letra do formato
// é um argumento engolido, e um "a" é um arquivo lido ("-f PADROES").
const PADRAO_OPCOES = {
  '-e': 't', '-f': 'a', '-m': 't', '-A': 't', '-B': 't', '-C': 't', '-d': 't', '-g': 't', '-t': 't', '-j': 't',
  '--regexp': 't', '--file': 'a', '--include': 't', '--exclude': 't', '--exclude-dir': 't', '--glob': 't',
  '--type': 't', '--max-count': 't', '--max-depth': 't',
}
const SED_OPCOES = { '-e': 't', '-f': 'a', '--expression': 't', '--file': 'a' }
const AWK_OPCOES = { '-F': 't', '-v': 't', '-f': 'a' }
const JQ_OPCOES = {
  '-f': 'a', '--from-file': 'a', '--arg': 'tt', '--argjson': 'tt', '--slurpfile': 'ta', '--rawfile': 'ta',
  '--indent': 't', '-L': 't',
}
const INTERPRETE_OPCOES = { '-c': 't', '-m': 't', '-e': 't', '--eval': 't', '-r': 't', '-W': 't', '-X': 't', '-o': 't' }
const TOUCH_OPCOES = { '-t': 't', '-d': 't', '-r': 't' }
const PATCH_OPCOES = { '-i': 'a', '--input': 'a', '-p': 't', '-d': 't' }

// Um heredoc some inteiro: o corpo é dado, não caminho. A linha de abertura
// fica, menos o `<<EOF`, porque pode ter um `> saida.txt` depois dele.
const semHeredocs = (comando: string): string => {
  const saida: string[] = []
  let fim: string | undefined

  for (const linha of comando.split('\n')) {
    if (fim !== undefined) {
      fim = linha.trim() === fim ? undefined : fim
      continue
    }

    const abertura = /(?<!<)<<(?!<)-?\s*(['"]?)(\w+)\1/.exec(linha)

    if (abertura === null) {
      saida.push(linha)
      continue
    }

    fim = abertura[2]
    saida.push(linha.replace(abertura[0], ' '))
  }

  return saida.join('\n')
}

// `''.includes('')` é verdadeiro: no fim do texto a letra é undefined.
const um = (letra: string | undefined, conjunto: string): boolean => letra !== undefined && conjunto.includes(letra)

// Separa o comando em trechos (entre &&, ||, ;, |, &, quebras de linha e
// parênteses) e cada trecho em palavras, respeitando aspas. Um > ou < fora
// de aspas vira uma palavra de redirecionamento, que marca a palavra seguinte.
const trechos = (comando: string): Palavra[][] => {
  const todos: Palavra[][] = []
  let trecho: Palavra[] = []
  let texto = ''

  const fechar = (): void => {
    if (texto !== '') {
      trecho.push({ texto })
    }

    texto = ''
  }

  const cortar = (): void => {
    fechar()

    if (trecho.length > 0) {
      todos.push(trecho)
    }

    trecho = []
  }

  for (let i = 0; i < comando.length; i += 1) {
    const c = comando[i] ?? ''
    const proximo = comando[i + 1] ?? ''

    if (c === "'") {
      const fim = comando.indexOf("'", i + 1)
      texto += comando.slice(i + 1, fim === -1 ? undefined : fim)
      i = fim === -1 ? comando.length : fim
    } else if (c === '"') {
      i += 1

      while (i < comando.length && comando[i] !== '"') {
        const isEscape = comando[i] === '\\' && um(comando[i + 1], '"\\$`')
        texto += (isEscape ? comando[i + 1] : comando[i]) ?? ''
        i += isEscape ? 2 : 1
      }
    } else if (c === '\\') {
      texto += proximo === '\n' ? '' : proximo
      i += 1
    } else if (c === '#' && texto === '') {
      const fim = comando.indexOf('\n', i)
      i = fim === -1 ? comando.length : fim - 1
    } else if (c === ' ' || c === '\t' || c === '\r') {
      fechar()
    } else if (c === '&' && proximo !== '>') {
      i += proximo === '&' ? 1 : 0
      cortar()
    } else if (';\n()`'.includes(c) || c === '|') {
      i += c === '|' && proximo === '|' ? 1 : 0
      cortar()
    } else if (c === '<' || c === '>' || c === '&') {
      // "2>": o número colado antes é o descritor, não um arquivo.
      texto = /^\d+$/.test(texto) ? '' : texto
      fechar()
      let op = c

      while (um(comando[i + 1], '<>&|')) {
        i += 1
        op += comando[i] ?? ''
      }

      // "2>&1" e ">&2" só trocam descritores: não há arquivo.
      if (op.endsWith('&') && /[\d-]/.test(comando[i + 1] ?? '')) {
        while (/[\d-]/.test(comando[i + 1] ?? '')) {
          i += 1
        }
      } else {
        trecho.push({ texto: op, redireciona: op.includes('<<') ? 'nada' : op.includes('>') ? 'editando' : 'lendo' })
      }
    } else {
      texto += c
    }
  }

  cortar()

  return todos
}

const normalizar = (caminho: string): string => {
  const partes: string[] = []

  for (const parte of caminho.split('/')) {
    if (parte === '..') {
      partes.pop()
    } else if (parte !== '' && parte !== '.') {
      partes.push(parte)
    }
  }

  return `/${partes.join('/')}`
}

// O que dá para chamar de arquivo: tem barra ou extensão, não é opção, não
// é só número, não termina em barra (isso é pasta).
const pareceArquivo = (texto: string): boolean =>
  !texto.startsWith('-') &&
  !texto.endsWith('/') &&
  !texto.startsWith('/dev/') &&
  !/^[\d.]+$/.test(texto) &&
  (texto.includes('/') || /\.\w+$/.test(texto))

// Separa opções de argumentos posicionais, engolindo o argumento das opções
// que têm um e anotando como lido o que o formato marca com "a".
const posicionais = (args: readonly string[], formatos: Record<string, string>, anotar: Anotar): string[] => {
  const sobram: string[] = []

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i] ?? ''

    if (arg === '--') {
      sobram.push(...args.slice(i + 1))
      break
    }

    if (!arg.startsWith('-')) {
      sobram.push(arg)
      continue
    }

    for (const letra of formatos[arg] ?? '') {
      i += 1

      if (letra === 'a') {
        anotar(args[i] ?? '', 'lendo')
      }
    }
  }

  return sobram
}

// grep, sed, awk, jq: o primeiro posicional é o padrão ou o programa, a não
// ser que ele já tenha vindo por -e/-f.
const depoisDoPadrao = (args: readonly string[], formatos: Record<string, string>, anotar: Anotar): string[] => {
  const sobram = posicionais(args, formatos, anotar)
  const temPadrao = args.some(arg => /^(-[ef]|--(expression|regexp|file|from-file)(=|$))/.test(arg))

  return temPadrao ? sobram : sobram.slice(1)
}

const temOpcao = (args: readonly string[], letra: string, longa: string): boolean =>
  args.some(arg => new RegExp(`^-[a-zA-Z]*${letra}`).test(arg) || arg.startsWith(longa))

// O que cada comando faz com seus argumentos.
const examinar = (nome: string, args: readonly string[], anotar: Anotar): void => {
  const tudo = (acao: Acao, formatos: Record<string, string> = {}): void =>
    posicionais(args, formatos, anotar).forEach(arg => anotar(arg, acao))

  if (LEITORES.has(nome)) {
    tudo('lendo')
  } else if (EDITORES.has(nome)) {
    tudo('editando')
  } else if (nome === 'touch' || nome === 'truncate') {
    tudo('editando', nome === 'touch' ? TOUCH_OPCOES : { '-s': 't' })
  } else if (nome === 'cp') {
    // As origens são lidas e o destino escrito; se o destino é uma pasta,
    // não dá para saber daqui.
    const sobram = posicionais(args, {}, anotar)

    if (sobram.length > 1) {
      sobram.forEach((arg, i) => anotar(arg, i === sobram.length - 1 ? 'editando' : 'lendo'))
    }
  } else if (PADROES.has(nome)) {
    // Num grep recursivo o argumento costuma ser pasta: só o que tem extensão.
    const isRecursivo = nome === 'rg' || temOpcao(args, '[rR]', '--recursive')
    depoisDoPadrao(args, PADRAO_OPCOES, anotar)
      .filter(arg => !isRecursivo || /\.\w+$/.test(arg))
      .forEach(arg => anotar(arg, 'lendo'))
  } else if (nome === 'sed') {
    const acao = temOpcao(args, 'i', '--in-place') ? 'editando' : 'lendo'
    depoisDoPadrao(args, SED_OPCOES, anotar).forEach(arg => anotar(arg, acao))
  } else if (AWKS.has(nome) || nome === 'jq') {
    depoisDoPadrao(args, nome === 'jq' ? JQ_OPCOES : AWK_OPCOES, anotar).forEach(arg => anotar(arg, 'lendo'))
  } else if (nome === 'perl') {
    // "-pe CODIGO", "-ne", "-E": o código vem na palavra seguinte.
    const formatos = Object.fromEntries(args.filter(arg => /^-\w*[eE]$/.test(arg)).map((arg): [string, string] => [arg, 't']))
    const acao = temOpcao(args, 'i', '--in-place') ? 'editando' : 'lendo'
    posicionais(args, formatos, anotar).forEach(arg => anotar(arg, acao))
  } else if (INTERPRETES.has(nome)) {
    // "python3 script.py arg": o script é lido; o resto é dele, não nosso.
    const [script] = posicionais(args, INTERPRETE_OPCOES, anotar)
    const isInline = args.some(arg => /^(-c|-e|--eval)$/.test(arg))

    if (script !== undefined && !isInline) {
      anotar(script, 'lendo')
    }
  } else if (nome === 'patch') {
    // O alvo do patch está dentro do .patch: só o -i dá para ver.
    posicionais(args, PATCH_OPCOES, anotar)
  }
}

export const arquivosDoComando = (comando: string, cwd: string): ArquivoDoComando[] => {
  const achados: ArquivoDoComando[] = []
  let pasta: string | undefined = cwd.startsWith('/') ? normalizar(cwd) : undefined

  // Variável, glob, URL, ~: não dá para saber o arquivo sem rodar.
  const resolver = (texto: string): string | undefined => {
    if (/[$*?[`{]/.test(texto) || texto.startsWith('~') || texto.includes('://')) {
      return undefined
    }

    if (texto.startsWith('/')) {
      return normalizar(texto)
    }

    return pasta === undefined ? undefined : normalizar(`${pasta}/${texto}`)
  }

  const anotar: Anotar = (texto, acao) => {
    const caminho = pareceArquivo(texto) ? resolver(texto) : undefined

    if (caminho !== undefined) {
      achados.push({ caminho, acao })
    }
  }

  try {
    for (const trecho of trechos(semHeredocs(comando))) {
      const palavras: string[] = []
      // Os alvos dos redirecionamentos, anotados depois dos argumentos do
      // comando: "cat a.txt > b.txt" lê a antes de escrever b.
      const redirecionados: [string, Acao][] = []

      for (let i = 0; i < trecho.length; i += 1) {
        const palavra = trecho[i] ?? { texto: '' }

        if (palavra.redireciona === undefined) {
          palavras.push(palavra.texto)
          continue
        }

        i += 1
        const alvo = trecho[i]

        if (palavra.redireciona !== 'nada' && alvo !== undefined) {
          redirecionados.push([alvo.texto, palavra.redireciona])
        }
      }

      while (palavras.length > 0 && (PREFIXOS.has(palavras[0] ?? '') || /^\w+=/.test(palavras[0] ?? ''))) {
        palavras.shift()
      }

      const [primeira, ...args] = palavras
      const nome = (primeira ?? '').replace(/^.*\//, '')

      // Um cd vale para os trechos seguintes, mesmo dentro de parênteses: um
      // subshell que muda de pasta é raro demais para valer o parser.
      if (nome === 'cd' || nome === 'pushd') {
        const alvo = args.find(arg => !arg.startsWith('-'))
        pasta = alvo === undefined ? undefined : resolver(alvo)
      } else if (nome !== '' && nome !== 'git') {
        examinar(nome, args, anotar)
      }

      redirecionados.forEach(([texto, acao]) => anotar(texto, acao))
    }
  } catch {
    // Um comando esquisito demais: fica o que já deu para ver.
  }

  // Um arquivo lido e depois escrito conta como editado, na ordem em que
  // apareceu.
  const unicos = new Map<string, Acao>()

  for (const achado of achados) {
    if (unicos.get(achado.caminho) !== 'editando') {
      unicos.set(achado.caminho, achado.acao)
    }
  }

  return [...unicos].slice(0, MAX_ARQUIVOS).map(([caminho, acao]) => ({ caminho, acao }))
}

files.hooks/formato.ts:
// Formatação em pt-BR, sem Intl: o ambiente do mod não tem DOM nem Node.

const BLOCOS = '▁▂▃▄▅▆▇█'

// Quantos pixels tem uma célula do painel no app Desktop: uma coluna (a
// largura de um dígito na fonte do app) e uma linha. Medidas nos prints do
// app: a coluna dos nomes da linha do tempo (39 colunas, 305 px) e as linhas
// de texto (19 px uma da outra). Os SVG e os botões invisíveis por cima deles
// (os nós do grafo, os indicadores) convertem pixels em células com elas: uma
// medida errada desloca os botões cada vez mais para a direita e para baixo.
export const PIXELS_POR_COLUNA = 7.8
export const PIXELS_POR_LINHA = 19

export const limitar = (valor: number, minimo: number, maximo: number): number =>
  Math.min(maximo, Math.max(minimo, valor))

export const decimal = (valor: number, casas: number): string =>
  valor.toFixed(casas).replace('.', ',')

const semZero = (texto: string): string => texto.replace(/,0$/, '')

export const tokens = (n: number): string => {
  const valor = Math.abs(n)

  if (valor < 1000) {
    return String(Math.round(valor))
  }

  if (valor < 1_000_000) {
    return `${semZero(decimal(valor / 1000, 1))}k`
  }

  return `${semZero(decimal(valor / 1_000_000, 1))}M`
}

export const dolar = (usd: number | undefined): string =>
  usd === undefined ? 'US$ –' : `US$ ${decimal(Math.max(0, usd), 2)}`

const dois = (n: number): string => String(n).padStart(2, '0')

export const duracao = (ms: number): string => {
  const segundos = Math.max(0, ms) / 1000

  if (segundos < 10) {
    return `${decimal(segundos, 1)}s`
  }

  if (segundos < 60) {
    return `${Math.floor(segundos)}s`
  }

  const minutos = Math.floor(segundos / 60)

  if (minutos < 60) {
    return `${minutos}m${dois(Math.floor(segundos % 60))}s`
  }

  return `${Math.floor(minutos / 60)}h${dois(minutos % 60)}`
}

// O tempo de algo que ainda está correndo: em segundos inteiros no primeiro
// minuto e, depois, só em minutos. Assim o painel não precisa ser redesenhado
// a cada segundo (cada desenho troca os botões no app e recria os gráficos).
export const duracaoViva = (ms: number): string => {
  const segundos = Math.floor(Math.max(0, ms) / 1000)

  if (segundos < 60) {
    return `${segundos}s`
  }

  const minutos = Math.floor(segundos / 60)

  if (minutos < 60) {
    return `${minutos} min`
  }

  return `${Math.floor(minutos / 60)}h${dois(minutos % 60)}`
}

export const renovaEm = (iso: string | undefined, agora: number): string | undefined => {
  if (iso === undefined) {
    return undefined
  }

  const quando = Date.parse(iso)

  if (Number.isNaN(quando)) {
    return undefined
  }

  const minutos = Math.ceil((quando - agora) / 60_000)

  if (minutos <= 0) {
    return 'agora'
  }

  if (minutos < 60) {
    return `${minutos}min`
  }

  const horas = Math.floor(minutos / 60)

  return horas < 48 ? `${horas}h${dois(minutos % 60)}` : `${Math.floor(horas / 24)}d`
}

export const barra = (percentual: number, largura: number): { cheio: string; vazio: string } => {
  const cheios = limitar(Math.round((percentual / 100) * largura), 0, largura)

  return { cheio: '█'.repeat(cheios), vazio: '░'.repeat(largura - cheios) }
}

export const grafico = (valores: readonly number[], teto: number): string => {
  const maximo = teto > 0 ? teto : Math.max(1, ...valores)

  return valores
    .map(valor => BLOCOS[limitar(Math.ceil((valor / maximo) * 8), 1, 8) - 1] ?? '▁')
    .join('')
}

// As marcas que o app põe em volta de um texto colado (<pasted_content id="…">
// e o fechamento): no pedido mostrado, só o texto.
export const semMarcas = (texto: string): string =>
  texto.replace(/<\/?pasted_content\b[^>]*>/g, '').replace(/^\s*\n/, '')

export const umaLinha = (texto: string): string => texto.replace(/\s+/g, ' ').trim()

export const curto = (texto: string, maximo: number): string =>
  texto.length > maximo ? `${texto.slice(0, Math.max(1, maximo - 1))}…` : texto

// Encurtado pelo meio: "feature/checkout-re…keeps-going". Num ramo ou num
// arquivo, o começo e o fim é que distinguem um do outro.
export const curtoNoMeio = (texto: string, maximo: number): string => {
  const letras = [...texto]

  if (letras.length <= maximo) {
    return texto
  }

  const cabem = Math.max(1, maximo - 1)
  const inicio = Math.ceil(cabem / 2)

  return `${letras.slice(0, inicio).join('')}…${letras.slice(letras.length - (cabem - inicio)).join('')}`
}

// O dia e a hora de um instante, no fuso do computador: "05/10" e "21:31".
const doisDigitos = (n: number): string => String(n).padStart(2, '0')

export const diaDoMes = (ms: number): string => {
  const data = new Date(ms)

  return `${doisDigitos(data.getDate())}/${doisDigitos(data.getMonth() + 1)}`
}

export const horaDoDia = (ms: number): string => {
  const data = new Date(ms)

  return `${doisDigitos(data.getHours())}:${doisDigitos(data.getMinutes())}`
}

// O dia e a hora de um instante, para um título: "05/10 às 20:30".
export const diaEHora = (ms: number): string => `${diaDoMes(ms)} às ${horaDoDia(ms)}`

export const primeiraLinha = (texto: string): string =>
  texto
    .split('\n')
    .map(linha => linha.trim())
    .find(linha => linha !== '') ?? ''

export const modeloCurto = (id: string): string =>
  id.replace(/^claude-/, '').replace(/-\d{8}$/, '')

export const relativo = (caminho: string, raiz: string): string =>
  raiz !== '' && caminho.startsWith(`${raiz}/`) ? caminho.slice(raiz.length + 1) : caminho

export const plural = (n: number, um: string, varios: string): string =>
  `${n} ${n === 1 ? um : varios}`

export const nomeDoLimite = (tipo: string): string => {
  if (tipo === 'five_hour') {
    return '5 h'
  }

  if (tipo === 'seven_day') {
    return '7 dias'
  }

  return tipo === 'spend_limit' ? 'gasto' : tipo
}

export const nomeCurtoDoLimite = (tipo: string): string => {
  if (tipo === 'five_hour') {
    return '5h'
  }

  if (tipo === 'seven_day') {
    return '7d'
  }

  return tipo === 'spend_limit' ? 'gasto' : tipo
}

// Markdown e Code só aceitam tab e quebra de linha como caracteres de
// controle: saem as sequências ANSI e o resto dos controles.
export const limpo = (texto: string): string =>
  texto
    .replace(/\u001b\[[0-9;?]*[ -/]*[@-~]/g, '')
    .replace(/\u001b\][^\u0007\u001b]*(\u0007|\u001b\\)/g, '')
    .replace(/\r\n?/g, '\n')
    .replace(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g, '')

// O fim de um texto longo, com o aviso do que ficou de fora.
export const cauda = (texto: string, maximo: number): string =>
  texto.length > maximo ? `… ${texto.length - maximo} caracteres antes\n${texto.slice(-maximo)}` : texto

export const cabeca = (texto: string, maximo: number): string =>
  texto.length > maximo ? `${texto.slice(0, maximo)}\n… mais ${texto.length - maximo} caracteres` : texto

// Um comando ou padrão com a pasta do projeto encurtada: /proj/src vira src,
// e /proj sozinho vira um ponto.
export const semRaiz = (texto: string, raiz: string): string =>
  raiz.length < 2 ? texto : texto.split(`${raiz}/`).join('').split(raiz).join('.')

