// O desenho das abas, a partir de dados prontos: nada aqui chama `$`.
// Os elementos vêm da tabela da superfície ($.ui.resolve) e os botões chamam
// as ações que o register.tsx passa.

import type {
  BoxProps,
  ButtonProps,
  CodeProps,
  ElementConstructor,
  InputProps,
  MarkdownProps,
  RenderElement,
  SvgProps,
  TextProps,
} from 'claude-code'

import type {
  LensItem,
  LensAba,
  LensAgente,
  LensCategoria,
  LensComando,
  LensContexto,
  LensDiffDoGit,
  LensEntrada,
  LensFichaDoAgente,
  LensFichaDoComando,
  LensFichaDoTurno,
  LensFoco,
  LensLimite,
  LensMensagem,
  LensLinha,
  LensGit,
  LensInventario,
  LensRodada,
